var POST_Handler = async (c) => {
  try {
    const emailData = c.req.valid("json");
    const { sendEmail: sendEmail2 } = await Promise.resolve().then(() => (init_service(), exports_service));
    const result = await sendEmail2(emailData);
    if (!result.success) {
      return c.json(HONO_ERROR("BAD_REQUEST", "Failed to send email", {
        issues: [{ message: result.error || "Unknown error occurred" }]
      }), HTTP.BAD_REQUEST);
    }
    return c.json(HONO_RESPONSE({
      message: "Email sent successfully",
      data: result.data
    }), HTTP.OK);
  } catch (error48) {
    return c.json(HONO_ERROR("INTERNAL_SERVER_ERROR", "Internal server error", {
      issues: [
        {
          message: error48 instanceof Error ? error48.message : "Unknown error occurred"
        }
      ]
    }), HTTP.INTERNAL_SERVER_ERROR);
  }
};

